<script setup>
import {vesselGroups} from './fields.js'
import {describeEnvironmentField} from '../../data/incidentWeather.js'
defineProps({event:Object,includeVessels:Boolean})
const show=value=>value==null||value===''?'Unknown / not supplied':Array.isArray(value)?value.join('; ')||'Not supplied':typeof value==='object'?JSON.stringify(value,null,2):value
const groups=[
 ['Locality',[['region','Region'],['province','Province'],['nearestPorts','Nearest port(s)']]],
 ['Narrative, response and preliminary findings',[['timeline','Key events timeline'],['crewResponse','Crew behavior / response'],['crewFactors','Crew behavior factors'],['potentialCauses','Potential causes (preliminary)'],['findingsOfCause','Findings of cause'],['initialActions','Initial response and actions'],['rescueRecovery','Rescue, recovery and salvage'],['damageTypes','Damage categories'],['certificates','Certificates / survey / inspection information'],['recommendations','Recommendations']]],
 ['Authority and supporting records',[['sourceType','Source type'],['sourceRef','Source reference'],['receivedDate','Received date'],['reportingAuthority','Reporting authority'],['sourceNotes','Source reliability / limitations'],['documentNotes','Document notes']]]
]
</script>
<template>
 <div class="intake-supplement">
  <q-expansion-item v-if="includeVessels" label="Vessel and voyage particulars" icon="directions_boat" class="q-mt-md"><section v-for="(vessel,index) in event.vessels" :key="index" class="q-pa-md"><h3 class="section-title">{{index+1}}. {{vessel.name||'Unnamed vessel'}} · {{show(vessel.role)}}</h3><div class="form-grid"><div v-for="[key,label] in vesselGroups.flatMap(group=>group.fields)" :key="key"><div class="muted">{{label}}</div><p>{{show(vessel[key])}}</p></div><div v-for="[key,label] in [['origin','Origin'],['destination','Destination'],['route','Route'],['cargoType','Cargo type'],['cargoQuantity','Cargo quantity'],['cargoUnit','Cargo unit']]" :key="key"><div class="muted">{{label}}</div><p>{{show(vessel.voyage?.[key])}}</p></div></div></section></q-expansion-item>
  <q-expansion-item v-for="[title,fields] in groups" :key="title" :label="title" :default-opened="fields.some(([key])=>Array.isArray(event[key])?event[key].length:!!event[key])" class="q-mt-md"><dl class="form-grid q-pa-md"><div v-for="[key,label] in fields" :key="key"><dt class="muted">{{label}}</dt><dd class="q-ml-none q-mt-xs" style="white-space:pre-wrap;overflow-wrap:anywhere">{{show(event[key])}}</dd></div></dl></q-expansion-item>
  <section class="q-mt-lg"><h3 class="section-title">Weather and sea conditions</h3><div class="form-grid"><div v-for="[key,label] in [['waveHeightM','Wave height (m)'],['windForce','Wind force (Beaufort)'],['visibility','Visibility'],['weatherDescription','Weather condition'],['seaState','Sea condition'],['currentTide','Current / tide'],['observedAt','Observation time (local)'],['source','Entered / reported source notes']]" :key="key"><div class="muted">{{label}}</div><p>{{['waveHeightM','windForce','visibility','weatherDescription','seaState','currentTide'].includes(key)?describeEnvironmentField(event.environment||{},key):show(event.environment?.[key])}}</p></div></div><q-expansion-item v-if="event.environment?.lookup" label="Weather lookup source and modelled context" icon="cloud"><div class="q-pa-md text-caption"><p>{{event.environment.lookup.provider||'Open-Meteo'}} · {{event.environment.lookup.kind}}</p><p>Requested occurrence: {{event.environment.lookup.request?.localDateTime}} {{event.environment.lookup.request?.timezone}}</p><p>Position: {{event.environment.lookup.request?.lat}}, {{event.environment.lookup.request?.lon}} · received {{event.environment.lookup.returnedAt}}</p><p>Applied model suggestions keep a separate source for each value. Manually edited values are shown as entered values.</p></div></q-expansion-item></section>
  <div v-if="includeVessels" class="form-grid"><div v-for="[key,label] in [['crew','Crew aboard'],['passengers','Passengers aboard'],['totalOnboard','Total persons aboard'],['shipCondition','Vessel condition'],['pollution','Pollution / environmental impact'],['notes','Consequence source / clarification']]" :key="key"><div class="muted">{{label}}</div><p>{{show(event.consequences?.[key])}}</p></div></div><p class="muted">Consequence observation / as-of: {{show(event.consequences?.observedAt)}}</p>
 </div>
</template>
